import {quadraticValue,torqueBalance,ART_FLOWER,ART_BACKGROUNDS,SPORT_SCENES,passClear} from './learning-model.js';
const W=640,H=360;
const fontDraws=new WeakMap();
function refreshFont(c,draw){if(!c.canvas||typeof document==='undefined'||!document.fonts)return;const existing=fontDraws.get(c);if(existing){existing.draw=draw;return;}const record={draw};fontDraws.set(c,record);document.fonts.load('700 24px "Dormi Gentle Pen"','가나다 123').then(()=>{if(c.canvas.isConnected)record.draw();}).catch(()=>{});}

function background(c,color='#f6f1dc'){c.fillStyle=color;c.fillRect(0,0,W,H);c.lineCap='round';c.textAlign='center';c.textBaseline='middle';}
function line(c,x,y,x2,y2,color='#82988c',w=3){c.strokeStyle=color;c.lineWidth=w;c.beginPath();c.moveTo(x,y);c.lineTo(x2,y2);c.stroke();}
function dot(c,x,y,r,color){c.fillStyle=color;c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.fill();}
function text(c,t,x,y,size=24,color='#203c41'){c.fillStyle=color;c.font=`700 ${size}px "Dormi Gentle Pen", sans-serif`;c.fillText(t,x,y);}
export function drawQuadratic(c,{domain=[-1,4],x=-1}){refreshFont(c,()=>drawQuadratic(c,{domain,x}));background(c,'#274e43');const X=x=>94+(x+1)*90,Y=y=>235-y*26;for(let xx=-1;xx<=4;xx++){line(c,X(xx),42,X(xx),340,'#497162',1);text(c,String(xx),X(xx),Y(0)+25,22,'#d6e4cf');}line(c,50,Y(0),597,Y(0),'#b7c8ad',2);line(c,X(0),25,X(0),344,'#b7c8ad',2);for(const y of [-4,5])text(c,String(y),X(0)-29,Y(y),22,'#d6e4cf');text(c,'x',607,Y(0),23,'#d6e4cf');text(c,'y',X(0),17,23,'#d6e4cf');const curve=(lo,hi,color,w)=>{c.strokeStyle=color;c.lineWidth=w;c.beginPath();for(let i=0;i<=100;i++){const xx=lo+(hi-lo)*i/100;i?c.lineTo(X(xx),Y(quadraticValue(xx))):c.moveTo(X(xx),Y(quadraticValue(xx)));}c.stroke();};curve(-1,4,'#607d6c',4);curve(...domain,'#f4e8b1',5);for(const xx of domain)dot(c,X(xx),Y(quadraticValue(xx)),7,'#f5d476');dot(c,X(x),Y(quadraticValue(x)),12,'#ffd55d');dot(c,X(x),Y(quadraticValue(x)),4,'#fffbea');}
export function drawTorque(c,{mass=2,distance=1}){refreshFont(c,()=>drawTorque(c,{mass,distance}));background(c);const b=torqueBalance(mass,distance),angle=b.direction==='left'?-.13:b.direction==='right'?.13:0,cx=265,cy=215,scale=80;const X=x=>cx+x*scale*Math.cos(angle),Y=x=>cy+x*scale*Math.sin(angle);c.fillStyle='#8caa99';c.beginPath();c.moveTo(cx,cy+7);c.lineTo(cx-33,310);c.lineTo(cx+33,310);c.closePath();c.fill();line(c,X(-2),Y(-2),X(3.5),Y(3.5),'#b68950',16);for(const x of[-1,1,2,3]){dot(c,X(x),Y(x),5,'#fff5d5');text(c,`${Math.abs(x)} m`,X(x),Y(x)+32,21);}for(const [x,massKg,color]of[[-1,mass,'#628b80'],[distance,1,'#c0816c']]){const h=massKg*20+24;c.fillStyle=color;c.fillRect(X(x)-24,Y(x)-h-10,48,h);text(c,`${massKg} kg`,X(x),Y(x)-h-31,24);}text(c,'받침점',cx,332,22);text(c,b.direction==='level'?'균형':'돌아가는 방향의 표시',330,28,26);}
export function drawArt(c,index=0){background(c,ART_BACKGROUNDS[index].color);for(let i=0;i<7;i++){const a=i*Math.PI*2/7;dot(c,320+Math.cos(a)*44,174+Math.sin(a)*44,31,ART_FLOWER);}dot(c,320,174,27,'#705438');line(c,320,238,320,304,'#436a48',9);}
export function drawPass(c,{scene=0,slot=1,passed=false}){refreshFont(c,()=>drawPass(c,{scene,slot,passed}));background(c,'#c4d5ac');for(const y of[15,345])line(c,30,y,610,y,'#fff7df',3);for(const x of[30,610])line(c,x,15,x,345,'#fff7df',3);line(c,320,15,320,345,'#e8eed4',2);const s=SPORT_SCENES[scene],p=s.slots[slot],clear=passClear(s.passer,p,s.defenders);if(passed)line(c,s.passer.x,s.passer.y,p.x,p.y,clear?'#346657':'#a45b46',8);for(const d of s.defenders){dot(c,d.x,d.y,d.r,'#c789744d');dot(c,d.x,d.y,19,'#ad6652');text(c,'수비',d.x,d.y+66,24);}dot(c,s.passer.x,s.passer.y,23,'#355e64');text(c,'패서',s.passer.x,s.passer.y+48,24);s.slots.forEach((p,i)=>{dot(c,p.x,p.y,i===slot?26:19,i===slot?'#f7d56c':'#f5efdc');text(c,String(i+1),p.x,p.y,24);});text(c,'받는 친구',523,328,22);}
